// Builds the post from the feed item and the article's page.
const article = $('New article').item.json;
const html = typeof $json.data === 'string' ? $json.data : '';
// The image the article shares on social media: its og:image tag, or else the feed's own image.
const tag = html.match(/<meta[^>]+property=["']og:image["'][^>]*>/i);
const fromPage = tag ? (tag[0].match(/content=["']([^"']+)["']/i) || [])[1] || '' : '';
const enclosure = article.enclosure || {};
const fromFeed = /^image\//.test(enclosure.type || '') ? enclosure.url : '';
const image = (fromPage || fromFeed || '').replace(/&amp;/g, '&');
const snippet = (article.contentSnippet || '').replace(/\s+/g, ' ').trim();
const summary = snippet.length > 200 ? snippet.slice(0, 200).replace(/\s+\S*$/, '') + '...' : snippet;
return {
  json: {
    text: [article.title, summary, article.link].filter(Boolean).join('\n\n'),
    image: /^https:\/\//.test(image) ? image : '',
  },
};
